//go:generate go run generate_zones.go

// Package tzgeo maps IANA time zone names (e.g. "Europe/Moscow") to the
// representative latitude and longitude of the zone's principal location,
// as published by IANA in the 'zone1970.tab' file that ships with every
// 'tzdata' Unix package.
//
// Zone data lives in ‘zones.go’, which is generated by running ‘go generate’.
package tzgeo

import (
	"maps"
	"slices"
)

// Zone describes a single row of zone1970.tab.
type Zone struct {
	// IANA name (for example "America/New_York").
	Name string
	// Location in degrees (+N, +E).
	Lat, Lon float64
	// ISO3166-1 alpha-2 codes that use this zone
	Countries []string
	// Free-form comments (possibly empty).
	Comments string
	// Position in the “zone1970.tab” file.
	Order int
}

// Lookup returns the representative coordinates of the given IANA zone name.
// ok is false if the name is unknown to the table.
func Lookup(name string) (lat, lon float64, ok bool) {
	z, ok := zones[name]
	return z.Lat, z.Lon, ok
}

// LookupZone is like Lookup but returns the full Zone record.
func LookupZone(name string) (Zone, bool) {
	z, ok := zones[name]
	return z, ok
}

// All returns every zone in the table in unspecified order.
// (The original order can be restored by sorting on the
// zone's Order field, if necessary.)
func All() []Zone {
	return slices.Collect(maps.Values(zones))
}
